query NewIssueContext($owner: String!, $repo: String!, $status: String!, $window: Int!, $assignee0: String!, $assignee1: String!) {
  repository(owner: $owner, name: $repo) {
    id
    labels(first: 100, orderBy: {field: NAME, direction: ASC}) {
      totalCount
      pageInfo { hasNextPage endCursor }
      nodes { id name }
    }
    milestones(first: 100, states: OPEN, orderBy: {field: NUMBER, direction: ASC}) {
      totalCount
      pageInfo { hasNextPage endCursor }
      nodes { id title dueOn }
    }
    assignee0: assignableUsers(query: $assignee0, first: 100) { nodes { id login } }
    assignee1: assignableUsers(query: $assignee1, first: 100) { nodes { id login } }
    issues(last: $window, states: OPEN, orderBy: {field: CREATED_AT, direction: ASC}) {
      nodes {
        id
        number
        title
        body
        viewerDidAuthor
        labels(first: 50) { nodes { name } }
        milestone { title dueOn }
        assignees(first: 10) { totalCount nodes { login } }
        projectItems(first: 20) {
          nodes {
            id
            isArchived
            project { id }
            fieldValueByName(name: $status) { ... on ProjectV2ItemFieldSingleSelectValue { name } }
          }
        }
      }
    }
  }
}

mutation NewFinish($issue: ID!, $assignees: [ID!]!) {
  assign: addAssigneesToAssignable(input: {assignableId: $issue, assigneeIds: $assignees}) { clientMutationId }
}

